<template>
  <div class="wrap">
    <div class="summary">
      <div class="k">
        <div class="label">Latest Trace</div>
        <div class="value mono">{{ activeRun.traceId || "-" }}</div>
      </div>
      <div class="k">
        <div class="label">Track</div>
        <div class="value track-badge" :class="activeRun.track">{{ activeRun.track || "-" }}</div>
      </div>
      <div class="k">
        <div class="label">Rounds</div>
        <div class="value">{{ runs.length }}</div>
      </div>
    </div>

    <div class="list">
      <div v-if="!runs || runs.length === 0" class="empty">发送问题后，这里会按轮次保存执行细节，默认只展开最近一轮。</div>

      <div v-else class="run-list">
        <details
          v-for="run in displayRuns"
          :key="run.id"
          class="run-card"
          :open="run.expanded"
          @toggle="onToggle(run.originalIndex, $event)"
        >
          <summary class="run-summary">
            <div class="run-main">
              <span class="run-title">{{ run.title }}</span>
              <span class="track-badge" :class="run.track">{{ run.track || "-" }}</span>
              <span class="run-status" :class="run.status">{{ runStatusText(run.status) }}</span>
            </div>
            <div class="run-meta mono">{{ run.traceId || "等待 Trace ID..." }}</div>
            <div class="run-count">{{ run.steps.length }} steps</div>
          </summary>

          <div class="timeline">
            <div v-for="(s, idx) in run.steps" :key="`${run.id}-${idx}`" class="timeline-item">
              <div class="timeline-marker" :class="s.status"></div>
              <div class="card">
                <div class="row">
                  <div class="name">{{ s.name }}</div>
                  <div class="status-icon" :class="s.status">
                    <span v-if="s.status === 'ok'">✓</span>
                    <span v-else-if="s.status === 'error'">✗</span>
                    <span v-else>•</span>
                  </div>
                </div>

                <div class="chips" v-if="s.provider || s.model || s.latency_ms != null">
                  <span v-if="s.provider" class="chip provider">{{ s.provider }}</span>
                  <span v-if="s.model" class="chip model">{{ s.model }}</span>
                  <span v-if="s.latency_ms != null" class="chip latency">{{ s.latency_ms }}ms</span>
                </div>

                <div class="details-group">
                  <details v-if="s.meta && Object.keys(s.meta).length" class="block">
                    <summary>Meta Data</summary>
                    <pre class="mono">{{ pretty(s.meta) }}</pre>
                  </details>

                  <details v-if="s.input_preview" class="block">
                    <summary>Input Preview</summary>
                    <pre class="mono">{{ s.input_preview }}</pre>
                  </details>

                  <details v-if="s.output" class="block">
                    <summary>Output</summary>
                    <pre class="mono">{{ s.output }}</pre>
                  </details>
                </div>

                <div v-if="s.error" class="error">
                  {{ s.error }}
                </div>
              </div>
            </div>
          </div>
        </details>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "StepDisplay",
  props: {
    runs: { type: Array, default: () => [] },
  },
  emits: ["toggle-run"],
  computed: {
    activeRun() {
      return this.runs[this.runs.length - 1] || { traceId: "", track: "", steps: [] };
    },
    displayRuns() {
      return [...this.runs]
        .map((run, index) => ({ ...run, originalIndex: index }))
        .reverse();
    },
  },
  methods: {
    pretty(obj) {
      try {
        return JSON.stringify(obj, null, 2);
      } catch {
        return String(obj);
      }
    },
    runStatusText(status) {
      if (status === "running") return "运行中";
      if (status === "error") return "失败";
      if (status === "aborted") return "已中断";
      return "已完成";
    },
    onToggle(index, event) {
      this.$emit("toggle-run", { index, open: event.target.open });
    },
  },
};
</script>


